/**
 * Seeds realistic sample data for local development.
 *
 *   npm run db:seed          -> only seeds when the database is empty (safe to re-run)
 *   npm run db:seed:reset    -> wipes all QueueDesk tables first, then seeds
 *
 * Status histories are generated by walking the same lifecycle the API enforces,
 * so seeded tickets look exactly like tickets created through the API.
 */
import { CommentAuthorType, PrismaClient, TicketPriority, TicketStatus } from '@prisma/client';

const prisma = new PrismaClient();

const HOUR = 60 * 60 * 1000;

interface SeedComment {
  by: 'customer' | 'agent';
  body: string;
  hoursAfterCreation: number;
}

interface SeedTicket {
  customer: string; // e-mail
  assignee?: string; // agent e-mail
  subject: string;
  description: string;
  priority: TicketPriority;
  /** Statuses visited after OPEN, in order; the last one is the current status. */
  path: Array<{ status: TicketStatus; hoursAfterCreation: number; note?: string }>;
  daysAgo: number;
  comments: SeedComment[];
}

