async function wipe(): Promise<void> {
  await prisma.ticketComment.deleteMany();
  await prisma.ticketStatusHistory.deleteMany();
  await prisma.ticket.deleteMany();
  await prisma.customer.deleteMany();
  await prisma.agent.deleteMany(); // Restart AUTOINCREMENT counters so a reset database always hands out ids 1..n again.
  await prisma.$executeRawUnsafe('DELETE FROM sqlite_sequence');
}

async function main(): Promise<void> {
  const reset = process.argv.includes('--reset');
  if (reset) {
    await wipe();
    console.log('Existing QueueDesk data removed (--reset).');
  } else if ((await prisma.customer.count()) > 0 || (await prisma.agent.count()) > 0) {
    console.log(
      'Database already contains data - skipping seed. Use `npm run db:seed:reset` to start over.',
    );
    return;
  }

  const customerIds = new Map<string, number>();
  for (const c of customers) {
    const created = await prisma.customer.create({ data: c });
    customerIds.set(c.email, created.id);
  }
  const agentIds = new Map<string, number>();
  for (const a of agents) {
    const created = await prisma.agent.create({ data: a });
    agentIds.set(a.email, created.id);
  }

  const now = Date.now();
  for (const t of tickets) {
    const createdAt = new Date(now - t.daysAgo * 24 * HOUR);
    const at = (hours: number) => new Date(createdAt.getTime() + hours * HOUR);
    const last = t.path.at(-1);
    const resolvedStep = t.path.find((p) => p.status === 'RESOLVED');
    const assigneeId = t.assignee ? agentIds.get(t.assignee) : undefined;

    const ticket = await prisma.ticket.create({
      data: {
        subject: t.subject,
        description: t.description,
        priority: t.priority,
        status: last?.status ?? 'OPEN',
        customerId: customerIds.get(t.customer)!,
        assigneeId,
        createdAt,
        resolvedAt:
          resolvedStep && last?.status !== 'IN_PROGRESS'
            ? at(resolvedStep.hoursAfterCreation)
            : null,
        closedAt: last?.status === 'CLOSED' ? at(last.hoursAfterCreation) : null,
        updatedAt: at(last?.hoursAfterCreation ?? 0),
      },
    });

    let previous: TicketStatus | null = null;
    const steps: Array<{ status: TicketStatus; hours: number; note?: string }> = [
      { status: 'OPEN', hours: 0, note: 'Ticket created' },
      ...t.path.map((p) => ({ status: p.status, hours: p.hoursAfterCreation, note: p.note })),
    ];
    for (const step of steps) {
      await prisma.ticketStatusHistory.create({
        data: {
          ticketId: ticket.id,
          fromStatus: previous,
          toStatus: step.status,
          note: step.note,
          changedByAgentId: previous === null ? null : (assigneeId ?? null),
          createdAt: at(step.hours),
        },
      });
      previous = step.status;
    }

    for (const c of t.comments) {
      const authorType: CommentAuthorType = c.by === 'agent' ? 'AGENT' : 'CUSTOMER';
      await prisma.ticketComment.create({
        data: {
          ticketId: ticket.id,
          authorType,
          agentId: authorType === 'AGENT' ? (assigneeId ?? null) : null,
          body: c.body,
          createdAt: at(c.hoursAfterCreation),
        },
      });
    }
  }

  console.log(
    `Seeded ${customers.length} customers, ${agents.length} agents and ${tickets.length} tickets.`,
  );
}

main()
  .catch((error: unknown) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
